func NewReportTestsFinishedEndpoint(s Service) goa.Endpoint {
	return func(ctx context.Context, req any) (any, error) {
		p := req.(*ReportTestsFinishedPayload)
		return s.ReportTestsFinished(ctx, p)
	}
}

